"""make_tables.py - WP4: collect the numbers of every result file into one Markdown file (WP4_summary_tables.md) so that the README and the manuscript revision quote files, not memory.
Reads results/index.csv, results/*__cons.csv, results/*__detection.csv, meta/*, metacell/metacell_summary.csv, perturbation/*. Writes WP4_summary_tables.md. No analysis.
Usage: python -I make_tables.py"""
import os, sys, json
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
sys.stdout.reconfigure(encoding='utf8')
import numpy as np, pandas as pd

HERE = os.path.dirname(os.path.abspath(__file__)); RES = os.path.join(HERE, 'results'); META = os.path.join(HERE, 'meta'); MC = os.path.join(HERE, 'metacell'); PERT = os.path.join(HERE, 'perturbation')
TAGS = ['gse81608', 'gse84133_human', 'gse86469', 'gse81547', 'emtab5061', 'gse84133_mouse']
NAME = {'gse81608': 'GSE81608', 'gse84133_human': 'GSE84133 human', 'gse86469': 'GSE86469', 'gse81547': 'GSE81547', 'emtab5061': 'E-MTAB-5061', 'gse84133_mouse': 'GSE84133 mouse'}
GENES = ['Hes1', 'Wnt5a', 'Wnt5b', 'Wnt9a', 'Lef1', 'Tcf7', 'Tcf7l2', 'Itpr1', 'Ryr2', 'Ryr3', 'Cacna1c', 'Cacna1d', 'Kcnj11', 'Ptbp1', 'Glut2', 'Ins1', 'Glp1r']


def f(x, d=3, sign=False):
    if x is None or (isinstance(x, float) and np.isnan(x)): return '-'
    return ('%+.*f' if sign else '%.*f') % (d, x)


def md(rows, header):
    L = ['| ' + ' | '.join(header) + ' |', '|' + '|'.join('---' for _ in header) + '|']
    for r in rows: L.append('| ' + ' | '.join(str(c) for c in r) + ' |')
    return '\n'.join(L)


I = pd.read_csv(os.path.join(RES, 'index.csv')); out = ['# WP4 summary tables (generated by make_tables.py from the result files; no analysis)', '']
# ---- Table 1
rows = []
for t in TAGS:
    u = I[(I.tag == t) & (I.variant == 'primary') & (I['mode'] == 'unadjusted')].iloc[0]; a = I[(I.tag == t) & (I.variant == 'primary') & (I['mode'] == 'adjusted')].iloc[0]
    rows.append([NAME[t], int(a.beta_cells), int(a.donors), int(a.t2d_beta_cells), a['kind'], a.depth_covariate, int(a.genes_evaluable), int(a.consensus_pairs_evaluable), f(u.median_rho_consensus, 3, True), f(u.null_median_rho_mean), f(a.median_rho_consensus, 3, True), f(a.null_median_rho_mean),
                 f(a.E, 3, True), f(a.SE_E), f(a.empirical_p_E), '%d / %d' % (a.consensus_sig_positive_q05, a.consensus_sig_negative_q05)])
out += ['## Table 1. Cell-level analysis of each dataset (all frozen beta-cells; primary variant)', '', md(rows, ['dataset', 'beta-cells', 'donors', 'beta-cells from T2D donors', 'data', 'depth covariate', 'evaluable genes (of 17)', 'evaluable consensus pairs (of 21)', 'median rho, not adjusted', 'matched-null median, not adjusted',
                                                                                                                       'median rho, depth-adjusted', 'matched-null median, depth-adjusted', 'E (depth-adjusted)', 'SE of E', 'empirical P of E', 'pairs q<0.05 positive / negative (depth-adjusted)']), '']
rows = []
for t in TAGS:
    for v in ('nondiabetic',):
        s = I[(I.tag == t) & (I.variant == v)]
        if len(s) == 0: continue
        for m in ('unadjusted', 'adjusted'):
            r = s[s['mode'] == m].iloc[0]; rows.append([NAME[t], m, int(r.beta_cells), int(r.donors), int(r.genes_evaluable), int(r.consensus_pairs_evaluable), f(r.median_rho_consensus, 3, True), f(r.null_median_rho_mean), f(r.E, 3, True), f(r.SE_E)])
out += ['## Table 1b. Sensitivity: non-diabetic donors only (datasets with donors who have type 2 diabetes)', '', md(rows, ['dataset', 'mode', 'beta-cells', 'donors', 'evaluable genes', 'evaluable consensus pairs', 'median rho', 'matched-null median', 'E', 'SE of E']), '']
# ---- Table 2: evaluable genes and pairs
det = {}
for t in TAGS: d = pd.read_csv(os.path.join(RES, f'{t}__primary__adjusted__detection.csv')); det[t] = d.set_index('gene_invitro')
rows = []
for t in TAGS:
    d = det[t]; ev = [g for g in GENES if bool(d.loc[g, 'evaluable'])]; ne = [g for g in GENES if not bool(d.loc[g, 'evaluable'])]
    rows.append([NAME[t], len(ev), ', '.join(ev), ', '.join(ne)])
out += ['## Table 2. Evaluable genes (detected in at least 10% of the beta-cells)', '', md(rows, ['dataset', 'n', 'evaluable', 'not evaluable']), '']
cons = pd.read_csv(os.path.join(RES, 'gse81608__primary__adjusted__pairs.csv')); cons = cons[cons.consensus_invitro][['gene1', 'gene2']].values.tolist(); rows = []
cc = {t: pd.read_csv(os.path.join(RES, f'{t}__primary__adjusted__cons.csv')).set_index(['gene1', 'gene2']) for t in TAGS}
for a, b in cons:
    cells = []
    for t in TAGS[:5]: cells.append(f(cc[t].loc[(a, b), 'rho'], 2, True) if (a, b) in cc[t].index else 'NE')
    rows.append([f'{a}-{b}'] + cells + [f(cc['gse84133_mouse'].loc[(a, b), 'rho'], 2, True) if (a, b) in cc['gse84133_mouse'].index else 'NE', sum((a, b) in cc[t].index for t in TAGS[:5])])
out += ['## Table 2b. The 21 consensus pairs: depth-adjusted partial Spearman rho per dataset (NE = not evaluable); last column = number of human datasets in which the pair is evaluable', '', md(rows, ['pair'] + [NAME[t] for t in TAGS] + ['human datasets evaluable']), '']
n0 = [f'{a}-{b}' for (a, b), r in zip(cons, rows) if r[-1] == 0]; out += ['Pairs not evaluable in any human dataset (%d): %s.' % (len(n0), ', '.join(n0)), '']
# ---- Table 3: meta-analysis
ms = json.load(open(os.path.join(META, 'meta_summary.json'))); rows = []
for v in ms['variants']:
    for e in v.get('estimators', []): rows.append([v['variant'], v['mode'], ', '.join(v['qualifying']), e['estimator'], f(e['mu'], 3, True), '[%s, %s]' % (f(e['lo'], 3, True), f(e['hi'], 3, True)), f(e['tau2'], 4), '%.0f%%' % (100 * e['I2']), e['verdict']])
out += ['## Table 3. Random-effects meta-analysis of E (margin +/-0.10; primary = depth-adjusted, all donors, REML + Hartung-Knapp)', '', md(rows, ['variant', 'mode', 'datasets', 'estimator', 'pooled E', '95% CI', 'tau2', 'I2', 'verdict by the fixed rule']), '']
rows = []
for v in ms['variants']:
    for e in v.get('leave_one_out', []): rows.append([v['variant'], v['mode'], e['left_out'], f(e['mu'], 3, True), '[%s, %s]' % (f(e['lo'], 3, True), f(e['hi'], 3, True)), e['verdict']])
out += ['## Table 3b. Leave-one-dataset-out (REML + Hartung-Knapp)', '', md(rows, ['variant', 'mode', 'left out', 'pooled E', '95% CI', 'verdict']), '']
P = pd.read_csv(os.path.join(META, 'pair_level_pooled_rho.csv')).sort_values('pooled_rho', ascending=False)
out += ['## Table 4. Pair-level pooled rho (consensus pairs evaluable in at least 3 human datasets; depth-adjusted; REML + Hartung-Knapp on Fisher z)', '',
        md([[f'{r.gene1}-{r.gene2}', r.datasets, r.rho_by_dataset.replace(';', ' / '), f(r.pooled_rho, 3, True), '[%s, %s]' % (f(r.lo, 3, True), f(r.hi, 3, True)), '%.0f%%' % (100 * r.I2)] for r in P.itertuples()], ['pair', 'datasets', 'rho by dataset (order of the dataset table)', 'pooled rho', '95% CI', 'I2']), '']
# ---- Table 5: metacell
p = os.path.join(MC, 'metacell_summary.csv')
if os.path.exists(p):
    M = pd.read_csv(p); rows = []
    def rg(m, lo, hi, d, sign=False, sep='-'): return '-' if (m is None or np.isnan(m)) else '%s (%s%s%s)' % (f(m, d, sign), f(lo, d, sign), (' to ' if sign else sep), f(hi, d, sign))
    for r in M.itertuples():
        rows.append([NAME.get(r.tag, r.tag), int(r.size), '%d / %d' % (r.partitions_with_pairs, r.partitions), f(r.donors_used_median, 0), f(r.metacells_median, 0), rg(r.genes_evaluable_med, r.genes_evaluable_min, r.genes_evaluable_max, 0),
                     rg(r.consensus_pairs_evaluable_med, r.consensus_pairs_evaluable_min, r.consensus_pairs_evaluable_max, 0), int(r.cell_level_pairs) if not np.isnan(r.cell_level_pairs) else '-',
                     f(r.cell_level_median_rho, 3, True), rg(r.median_rho_med, r.median_rho_min, r.median_rho_max, 3, True), rg(r.E_med, r.E_min, r.E_max, 3, True), f(r.SE_E_med)])
    out += ['## Table 5. Metacell sensitivity (20 random partitions per size; median and range over the partitions; evaluable = nonzero in at least 50% of metacells)', '',
            md(rows, ['dataset', 'metacell size', 'partitions with an evaluable pair', 'donors used', 'metacells', 'evaluable genes', 'evaluable consensus pairs', 'cell level: pairs (10% rule)', 'cell level: median rho', 'metacell median rho', 'metacell E', 'median SE of E']), '']
# ---- Table 6: perturbation
C = pd.read_csv(os.path.join(PERT, 'candidates_decisions.csv')); g = json.load(open(os.path.join(PERT, 'gse60803_concordance.json')))
out += ['## Table 6. Perturbation concordance (protocol 4.6)', '', 'Candidates from the two fixed queries: %d unique series (%s); kept %d, dropped %d.' % (len(C), ', '.join('%s %d' % (k, v) for k, v in C.decision.value_counts().items()), (C.decision == 'keep').sum(), (C.decision == 'drop').sum()), '']
rows = []
for k, lab in (('all_donors', 'primary: 4 donors, perturbed mean minus control'), ('S114_only', 'secondary: donor S114 only (nontarget control, n = 1)')):
    d = g[k]; rows.append([lab, d['n_genes'], d['n_same_sign'], f(d['binomial_p']), f(d['spearman_rho'], 3, True), f(d['spearman_p'])])
out += [md(rows, ['GSE60803 contrast against the INS-1 DKK-1 arm', 'genes', 'same sign', 'exact binomial P', 'Spearman rho', 'P of rho']), '', 'Same sign (primary): ' + ', '.join(g['all_donors']['same_sign_genes']) + '. Opposite sign: ' + ', '.join(g['all_donors']['opposite_sign_genes']) + '.', '']
open(os.path.join(HERE, 'WP4_summary_tables.md'), 'w', encoding='utf8').write('\n'.join(out)); print('written WP4_summary_tables.md,', len(out), 'blocks')
